		_fishing_panel = FishingPanel.new()
		_hud.add_child(_fishing_panel)
		_fishing_panel.open_spot(e.eid)
		_fishing_panel.closed.connect(func():
			_fishing_panel = null
			_refresh_hud())
		e.trade_cooled = true
		return
